import heapq

def rooms(meetings):
    heap = []                      # end times of rooms in use
    for start, end in sorted(meetings):
        if heap and heap[0] <= start:
            heapq.heappop(heap)     # reuse the room that frees up first
        heapq.heappush(heap, end)
    return len(heap)

